<?php
declare(strict_types=1); require_once __DIR__.'/server/includes/bootstrap.php'; require_once __DIR__.'/server/includes/view.php'; $user=require_login($pdo); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$current=(string)($_POST['current_password']??'');$new=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');$q=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([(int)$user['id']]);$hash=(string)$q->fetchColumn();if(!password_verify($current,$hash))$error='Current password does not match.';elseif(!valid_password($new)||$new!==$confirm)$error='New passwords must match and contain at least 6 characters.';elseif(password_verify($new,$hash))$error='Choose a password different from the current one.';else{$pdo->prepare('UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$user['id']]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([(int)$user['id']]);session_regenerate_id(true);audit($pdo,(int)$user['id'],'PASSWORD_CHANGED','Password changed in account portal');flash('success','Password changed successfully.');redirect($user['role']==='admin'?'/admin.php':'/dashboard.php');}}
page_header($config,$user,'Change password'); ?><section class="auth-wrap"><div class="auth-card"><div class="eyebrow">Account security</div><h1>Change password</h1><p>Signed in as <?=e($user['username'])?>. Your password is stored as a hash and cannot be viewed by admins.</p><?php if(!empty($user['must_change_password'])): ?><div class="flash warning">An admin has assigned a temporary password. Change it before accessing your account.</div><?php endif; ?><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><?=csrf_field()?><label class="field">Current or temporary password<input type="password" name="current_password" autocomplete="current-password" required></label><label class="field">New password<input type="password" name="password" minlength="6" autocomplete="new-password" required></label><label class="field">Confirm new password<input type="password" name="confirm_password" minlength="6" autocomplete="new-password" required></label><button class="btn gold" type="submit">Update password</button></form><?php if(empty($user['must_change_password'])): ?><p class="hint"><a href="<?= $user['role']==='admin'?'/admin.php':'/dashboard.php' ?>">Back to portal</a></p><?php endif; ?></div></section><?php page_footer(); ?>